import zipfile,re,html,os
from pathlib import Path
best=[]
for f in Path('documents/matters').rglob('*.docx'):
    try:
      with zipfile.ZipFile(f) as z: x=z.read('word/document.xml').decode('utf-8')
      # create plain text, preserving paragraph breaks
      x=re.sub(r'</w:p>', '\n', x); x=re.sub(r'<w:tab[^>]*/>', '\t', x); x=re.sub(r'<[^>]+>', '', x); text=html.unescape(x)
      low=text.lower()
      if 'settlement' not in low: continue
      # all numeric dollar values in windows around settlement-related terms
      vals=[]
      for m in re.finditer(r'(?i)(?:settlement amount|settlement payment|gross settlement amount|lump[- ]sum settlement payment|total settlement|payment amount|settlement consideration|settlement proceeds|settlement fund).{0,500}',text):
        s=m.group(0)
        for n in re.findall(r'\$\s*([0-9][0-9,]*(?:\.\d+)?)',s):
          try: vals.append(float(n.replace(',','')))
          except: pass
      if vals:
        best.append((max(vals),str(f),sorted(set(vals),reverse=True)[:5]))
    except: pass
for row in sorted(best, reverse=True)[:100]: print(row)
print('candidate docs',len(best))
